# list_intersect :: ([1, 2, 3, 4], [2, 4, 6])
def list_intersect(a, b):
    bset = set(b)
    seen = set()
    out = []
    for x in a:
        if x in bset and x not in seen:
            seen.add(x)
            out.append(x)
    return out

if __name__ == '__main__':
    print(list_intersect(([1, 2, 3, 4], [2, 4, 6])))

